import{c as a,S as r,j as i,m as l}from"./chunks/framework.8aa1YH_s.js";const g=JSON.parse('{"title":"Türk Dil Bilgisi Serisi - 7: Türkçedeki Ses Hadiseleri (Ses Olayları)","description":"","frontmatter":{},"headers":[],"relativePath":"7 Türkçedeki Ses Hadiseleri (Ses Olayları).md","filePath":"7 Türkçedeki Ses Hadiseleri (Ses Olayları).md"}'),n={name:"7 Türkçedeki Ses Hadiseleri (Ses Olayları).md"};function s(o,e,t,k,m,u){return r(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="turk-dil-bilgisi-serisi-7-turkcedeki-ses-hadiseleri-ses-olayları" tabindex="-1">Türk Dil Bilgisi Serisi - 7: Türkçedeki Ses Hadiseleri (Ses Olayları) <a class="header-anchor" href="#turk-dil-bilgisi-serisi-7-turkcedeki-ses-hadiseleri-ses-olayları" aria-label="Permalink to “Türk Dil Bilgisi Serisi - 7: Türkçedeki Ses Hadiseleri (Ses Olayları)”">​</a></h1><p>Ses bilgisi yolculuğumuzun bu bölümünde, dilimizin kurallarının kelime üzerinde nasıl canlandığını, ekler geldikçe seslerin nasıl şekil değiştirdiğini inceliyoruz. Prof. Dr. Muharrem Ergin&#39;e göre <strong>Ses Hadiseleri</strong>, konuşma organlarının en az çaba ilkesiyle çalışması, söyleyiş kolaylığı sağlama arzusu ve Türkçenin asli ses kanunlarının birer sonucudur.</p><p>Bu yazımızda, Türkçede en sık karşılaşılan asli ses hadiselerini 4 ana grupta ele alacağız: <strong>Ses Düşmesi, Ses Türemesi, Ses Benzeşmesi (Uyumlar) ve Ses Değişmesi (Yumuşama)</strong>.</p><hr><h2 id="_1-ses-dusmesi-vokal-ve-konsonant-dusmesi" tabindex="-1">1. Ses Düşmesi (Vokal ve Konsonant Düşmesi) <a class="header-anchor" href="#_1-ses-dusmesi-vokal-ve-konsonant-dusmesi" aria-label="Permalink to “1. Ses Düşmesi (Vokal ve Konsonant Düşmesi)”">​</a></h2><p>Kelimelerin çekimlenmesi veya türetilmesi esnasında, bazı seslerin zayıflayarak dilden tamamen kaybolması hadisesidir.</p><h3 id="a-vokal-unlu-dusmesi-hece-dusmesi" tabindex="-1">A) Vokal (Ünlü) Düşmesi / Hece Düşmesi <a class="header-anchor" href="#a-vokal-unlu-dusmesi-hece-dusmesi" aria-label="Permalink to “A) Vokal (Ünlü) Düşmesi / Hece Düşmesi”">​</a></h3><p>Türkçede özellikle son hecesinde <strong>dar ünlü (ı, i, u, ü)</strong> bulunan bazı iki heceli kelimeler, ünlüyle başlayan bir ek aldıklarında son hecedeki dar ünlülerini kaybederler.</p><ul><li><em>Örnekler:</em> * Ağız + ı $$\\rightarrow$$ <strong>Ağzı</strong><ul><li>Akıl + ım $$\\rightarrow$$ <strong>Aklım</strong></li><li>Boyun + u $$\\rightarrow$$ <strong>Boynu</strong></li><li>Devir + mek $$\\rightarrow$$<strong>Devirmek$$\\rightarrow$$ Devrim</strong> (Türetilirken düşme)</li></ul></li></ul><h3 id="b-konsonant-unsuz-dusmesi" tabindex="-1">B) Konsonant (Ünsüz) Düşmesi <a class="header-anchor" href="#b-konsonant-unsuz-dusmesi" aria-label="Permalink to “B) Konsonant (Ünsüz) Düşmesi”">​</a></h3><p>Genellikle sonu <strong>&quot;k&quot;</strong> ünsüzü ile biten kelimelere küçültme (<code>-cik, -cek</code>) veya sevgi ekleri getirildiğinde kelime sonundaki &quot;k&quot; sesi düşer.</p><ul><li><em>Örnekler:</em><ul><li>Küçük + cük $$\\rightarrow$$ <strong>Küçücük</strong></li><li>Sıcak + cık $$\\rightarrow$$ <strong>Sıcacık</strong></li><li>Yüksek + lmek $$\\rightarrow$$ <strong>Yükselmek</strong></li></ul></li></ul><hr><h2 id="_2-ses-turemesi-vokal-ve-konsonant-turemesi" tabindex="-1">2. Ses Türemesi (Vokal ve Konsonant Türemesi) <a class="header-anchor" href="#_2-ses-turemesi-vokal-ve-konsonant-turemesi" aria-label="Permalink to “2. Ses Türemesi (Vokal ve Konsonant Türemesi)”">​</a></h2><p>Kelimelerin ek alması veya başka bir kelimeyle birleşmesi sırasında, aslında kökte veya ekte olmayan yeni bir sesin ortaya çıkmasıdır.</p><h3 id="a-vokal-unlu-turemesi" tabindex="-1">A) Vokal (Ünlü) Türemesi <a class="header-anchor" href="#a-vokal-unlu-turemesi" aria-label="Permalink to “A) Vokal (Ünlü) Türemesi”">​</a></h3><p>Tek heceli olan veya sonu ünsüzle biten bazı kelimelere küçültme eki getirildiğinde araya bir ünlü sıkışır.</p><ul><li><em>Örnekler:</em><ul><li>Az + cık $$\\rightarrow$$ <strong>Azıcık</strong></li><li>Dar + cık $$\\rightarrow$$ <strong>Daracık</strong></li><li>Bir + cik $$\\rightarrow$$ <strong>Biricik</strong></li></ul></li></ul><h3 id="b-konsonant-unsuz-turemesi" tabindex="-1">B) Konsonant (Ünsüz) Türemesi <a class="header-anchor" href="#b-konsonant-unsuz-turemesi" aria-label="Permalink to “B) Konsonant (Ünsüz) Türemesi”">​</a></h3><p>Genellikle dilimize Arapçadan giren ve aslında asıl dilde ikiz ünsüz barındıran bazı kelimeler, Türkçede tek ünsüzle yazılırlar (<em>red, af, his</em>). Ancak bu kelimeler yardımcı fiillerle (<code>etmek, olmak</code>) birleştiğinde veya ünlüyle başlayan ek aldıklarında asıl yapıdaki ünsüz ortaya çıkar.</p><ul><li><em>Örnekler:</em><ul><li>His + etmek $$\\rightarrow$$ <strong>Hissetmek</strong></li><li>Af + etmek $$\\rightarrow$$ <strong>Affetmek</strong></li><li>Sır + ı $$\\rightarrow$$ <strong>Sırrı</strong></li></ul></li></ul><hr><h2 id="_3-konsonant-benzesmesi-unsuz-uyumları-sertlesme" tabindex="-1">3. Konsonant Benzeşmesi (Ünsüz Uyumları / Sertleşme) <a class="header-anchor" href="#_3-konsonant-benzesmesi-unsuz-uyumları-sertlesme" aria-label="Permalink to “3. Konsonant Benzeşmesi (Ünsüz Uyumları / Sertleşme)”">​</a></h2><p>Türkçede sert (sedasız) ünsüzlerin yan yana gelme eğiliminin bir sonucudur. Muharrem Ergin&#39;e göre bu durum, seslerin birbiri üzerindeki asimilasyon (kendine benzetme) etkisidir.</p><ul><li><p><strong>Kural:</strong> Sonu sert bir ünsüzle (<strong>ç, f, h, k, p, s, ş, t</strong>) biten bir kelimeye yumuşak ünsüzlerden olan <strong>&quot;c, d, g&quot;</strong> ile başlayan bir ek getirilirse, ekin başındaki ünsüz sertleşerek <strong>&quot;ç, t, k&quot;</strong> seslerine dönüşür.</p></li><li><p><em>Örnekler:</em></p><ul><li>Kitap + cı $$\\rightarrow$$<strong>Kitapçı</strong> (c$$\\rightarrow$$ ç oldu)</li><li>Ağaç + dan $$\\rightarrow$$<strong>Ağaçtan</strong> (d$$\\rightarrow$$ t oldu)</li><li>Çalış + gan $$\\rightarrow$$<strong>Çalışkan</strong> (g$$\\rightarrow$$ k oldu)</li></ul></li></ul><hr><h2 id="_4-konsonant-degismesi-unsuz-yumusaması" tabindex="-1">4. Konsonant Değişmesi (Ünsüz Yumuşaması) <a class="header-anchor" href="#_4-konsonant-degismesi-unsuz-yumusaması" aria-label="Permalink to “4. Konsonant Değişmesi (Ünsüz Yumuşaması)”">​</a></h2><p>Türkçede süreksiz sert ünsüzlerin (<strong>p, ç, t, k</strong>), iki ünlü arasında kalarak veya ünlüyle karşılaşarak yumuşaması, yani sedalı (tonlu) karşılıklarına dönüşmesi hadisesidir.</p><ul><li><p><strong>Kural:</strong> Sonu <em>p, ç, t, k</em> ile biten bir kelimeye, ünlüyle başlayan bir ek getirildiğinde bu sesler sırasıyla <strong>b, c, d, g/ğ</strong> seslerine dönüşür.</p></li><li><p><em>Örnekler:</em></p><ul><li>Kitap + ı $$\\rightarrow$$<strong>Kitabı</strong> (p$$\\rightarrow$$ b)</li><li>Ağaç + a $$\\rightarrow$$<strong>Ağaca</strong> (ç$$\\rightarrow$$ c)</li><li>Kağıt + ı $$\\rightarrow$$<strong>Kağıdı</strong> (t$$\\rightarrow$$ d)</li><li>Renk + i $$\\rightarrow$$<strong>Rengi</strong> (k$$\\rightarrow$$ g)</li><li>Yaprak + ı $$\\rightarrow$$<strong>Yaprağı</strong> (k$$\\rightarrow$$ ğ)</li></ul></li></ul><blockquote><p><strong>⚠️ Önemli İstisnalar:</strong> &gt; 1. Tek heceli kelimelerin çoğunda yumuşama olmaz: <em>Süt -&gt; Sütü</em>, <em>Koç -&gt; Koçu</em>, <em>İp -&gt; İpi</em>. 2. Özel isimler yazıda korunur, sadece telaffuzda yumuşatılır: <em>Zonguldak&#39;a</em> yazılır, <em>Zonguldağ&#39;a</em> okunur. 3. Yabancı dillerden geçen bazı kelimelerde yumuşama görülmez: <em>Hukuk -&gt; Hukuku</em>, <em>Millet -&gt; Milleti</em>, <em>Tabiat -&gt; Tabiatı</em>.</p></blockquote><hr><h2 id="ozet" tabindex="-1">Özet <a class="header-anchor" href="#ozet" aria-label="Permalink to “Özet”">​</a></h2><p>Prof. Dr. Muharrem Ergin&#39;in detaylandırdığı bu ses hadiseleri, Türkçenin fonetik yapısını koruyan ve konuşma esnasında dilin akıcılığını bozan pürüzleri temizleyen doğal mekanizmalardır. Sertleşmeler, yumuşamalar ve düşmeler sayesinde kelimeler eklerle tam bir uyum yakalar ve ortaya Türkçenin o ahenkli yapısı çıkar.</p><p>Böylelikle kitabın <strong>&quot;Ses Bilgisi (Fonetik)&quot;</strong> kısmını tamamen bitirmiş olduk aslanım!</p><p>Serimizin 8. bölümünde dil bilgisinin en büyük ikinci kalesi olan <strong>&quot;Şekil Bilgisi (Morfoloji) - Kelime Yapısı, Kökler ve Hece&quot;</strong> konusuna adım atacağız.</p><p>Yolumuz uzun, tempomuz yüksek. Geçelim mi bir sonrakine?</p>',36)])])}const $=a(n,[["render",s]]);export{g as __pageData,$ as default};
